export const customerOrders = sqliteTable('customer_orders', {
  id: text('id').primaryKey(),
  orderNumber: text('order_number').notNull().unique(), // CO-0001
  customerId: text('customer_id').notNull().references(() => customers.id),
  status: text('status', { enum: ['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'] })
    .notNull().default('pending'),
  totalPriceNet: integer('total_price_net', { mode: 'number' }).notNull(), // locked at creation, cents
  expectedDeliveryDate: integer('expected_delivery_date', { mode: 'timestamp' }),
  internalNotes: text('internal_notes'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('customer_orders_customer_id_idx').on(table.customerId),
  statusIdx: index('customer_orders_status_idx').on(table.status),
}))

export type CustomerOrder = typeof customerOrders.$inferSelect
export type NewCustomerOrder = typeof customerOrders.$inferInsert

/** Line items for customer orders */
export const customerOrderLineItems = sqliteTable('customer_order_line_items', {
  id: text('id').primaryKey(),
  orderId: text('customer_order_id').notNull().references(() => customerOrders.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  orderIdIdx: index('customer_order_line_items_order_id_idx').on(table.orderId),
  ...lineItemChecks(),
}))

export type CustomerOrderLineItem = typeof customerOrderLineItems.$inferSelect
export type NewCustomerOrderLineItem = typeof customerOrderLineItems.$inferInsert

